-- Source-database regression. Confirm standby epoch first; all test mutations roll back.
BEGIN; SET LOCAL lock_timeout='5s'; SET LOCAL statement_timeout='20s';
SELECT role,epoch FROM public.harkas_resilience_state WHERE singleton=true FOR UPDATE;
SELECT writer,epoch FROM public.harkas_failover_control WHERE resource='harkas-admin-db' FOR UPDATE;
UPDATE public.harkas_resilience_lease l SET expires_at=now()+interval '10 minutes',renewed_at=now() WHERE singleton=true AND node='supabase' AND EXISTS(SELECT 1 FROM public.harkas_resilience_state r JOIN public.harkas_failover_control c ON c.resource='harkas-admin-db' WHERE r.singleton=true AND r.role='primary' AND c.writer='supabase' AND c.epoch=r.epoch AND l.epoch=r.epoch);
DO $test$
DECLARE uid uuid; cid uuid; iid uuid:=gen_random_uuid(); draft jsonb; inv jsonb; qid uuid:=gen_random_uuid(); quote_data jsonb; converted jsonb; again jsonb; blocked boolean; old_version integer; new_number text;
BEGIN
 SELECT user_id INTO uid FROM public.user_roles WHERE role='admin' LIMIT 1;
 SELECT id INTO cid FROM public.customers ORDER BY created_at LIMIT 1;
 IF uid IS NULL OR cid IS NULL THEN RAISE EXCEPTION 'No test context'; END IF;
 PERFORM set_config('request.jwt.claim.sub',uid::text,true);
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',uid,'role','authenticated')::text,true);
 draft:=jsonb_build_object('id',iid,'expected_version',0,'customer_id',cid,'invoice_date','2098-01-01','due_date','2098-01-15','status','concept','items',jsonb_build_array(jsonb_build_object('description','ROLLBACK ONLY','quantity',1,'price',1.005,'vat_percentage',21)));
 inv:=public.save_invoice(draft);
 IF (inv->>'total')::numeric<>1.22 OR (inv->>'edit_version')::integer<>1 OR (SELECT subtotal FROM public.invoice_items WHERE invoice_id=iid)<>1.01 THEN RAISE EXCEPTION 'Atomic save or NUMERIC rounding failed'; END IF;
 blocked:=false;
 BEGIN PERFORM public.save_invoice(draft); EXCEPTION WHEN serialization_failure THEN blocked:=true; END;
 IF NOT blocked OR (SELECT count(*) FROM public.invoices WHERE id=iid)<>1 THEN RAISE EXCEPTION 'Creation retry was not protected'; END IF;
 UPDATE public.invoices SET pdf_storage_path='test-only-old.pdf' WHERE id=iid;
 SELECT edit_version INTO old_version FROM public.invoices WHERE id=iid;
 inv:=public.save_invoice(draft||jsonb_build_object('expected_version',old_version,'items',jsonb_build_array(jsonb_build_object('description','Updated test','quantity',2,'price',1.005,'vat_percentage',21))));
 IF (inv->>'total')::numeric<>2.43 OR inv->>'pdf_storage_path' IS NOT NULL OR (inv->>'edit_version')::integer<>old_version+1 THEN RAISE EXCEPTION 'Atomic update or PDF invalidation failed'; END IF;
 blocked:=false;
 BEGIN PERFORM public.save_invoice(draft||jsonb_build_object('expected_version',old_version)); EXCEPTION WHEN serialization_failure THEN blocked:=true; END;
 IF NOT blocked THEN RAISE EXCEPTION 'Stale editor overwrite was allowed'; END IF;
 blocked:=false;
 BEGIN PERFORM public.save_invoice(draft||jsonb_build_object('expected_version',old_version+1,'items',jsonb_build_array(jsonb_build_object('description','Invalid','quantity',1,'price',-1,'vat_percentage',21)))); EXCEPTION WHEN raise_exception THEN blocked:=true; END;
 IF NOT blocked OR (SELECT total FROM public.invoices WHERE id=iid)<>2.43 OR (SELECT subtotal FROM public.invoice_items WHERE invoice_id=iid)<>2.01 THEN RAISE EXCEPTION 'Invalid save damaged existing header or lines'; END IF;
 IF EXISTS(SELECT 1 FROM public.invoice_counters WHERE invoice_year=2097) THEN RAISE EXCEPTION 'Test year already in use'; END IF;
 INSERT INTO public.invoice_counters(invoice_year,last_number) VALUES(2097,999);
 new_number:=public.generate_invoice_number(2097);
 IF new_number<>'2097-1000' THEN RAISE EXCEPTION 'Invoice number was truncated: %',new_number; END IF;
 quote_data:=public.save_quote(jsonb_build_object('id',qid,'version',0,'customer_id',cid,'title','ROLLBACK ONLY - conversion','quote_date','2099-01-01','valid_until','2099-12-31','discount_percentage',33,'items',jsonb_build_array(jsonb_build_object('description','Discounted test','quantity',1,'price',1.5,'vat_percentage',21))));
 quote_data:=public.set_quote_status(qid,(quote_data->>'version')::integer,'geaccepteerd');
 converted:=public.convert_quote_to_invoice(qid,(quote_data->>'version')::integer);
 again:=public.convert_quote_to_invoice(qid,(quote_data->>'version')::integer);
 IF converted->>'invoice_id' IS DISTINCT FROM again->>'invoice_id' OR (SELECT total FROM public.invoices WHERE id=(converted->>'invoice_id')::uuid)<>1.22 THEN RAISE EXCEPTION 'Conversion duplicated or changed totals'; END IF;
 blocked:=false;
 BEGIN UPDATE public.invoices SET deleted_at=now() WHERE id=(converted->>'invoice_id')::uuid; EXCEPTION WHEN raise_exception THEN blocked:=true; END;
 IF NOT blocked THEN RAISE EXCEPTION 'Linked invoice deletion was allowed'; END IF;
 blocked:=false;
 BEGIN UPDATE public.invoices SET customer_id=NULL WHERE id=(converted->>'invoice_id')::uuid; EXCEPTION WHEN raise_exception THEN blocked:=true; END;
 IF NOT blocked THEN RAISE EXCEPTION 'Linked customer reassignment was allowed'; END IF;
 PERFORM set_config('request.jwt.claim.sub',gen_random_uuid()::text,true);
 blocked:=false;
 BEGIN PERFORM public.save_invoice(draft); EXCEPTION WHEN insufficient_privilege THEN blocked:=true; END;
 IF NOT blocked THEN RAISE EXCEPTION 'Unauthorized invoice save was allowed'; END IF;
END $test$;
ROLLBACK;
SELECT 'invoice save, rounding, stale edits, duplicate creation, conversion, linked protection and number 1000 passed; all test writes rolled back' AS result,(SELECT count(*) FROM public.invoices) AS invoices,(SELECT count(*) FROM public.invoice_items) AS invoice_items,(SELECT count(*) FROM public.quotes) AS quotes;
